use verus::prelude::*;

verus! {

    /// Pluralize a word (given as Vec<char>).
    ///   - If the word is empty, it returns empty.
    ///   - If the last character is 's', it appends "es".
    ///   - Otherwise it appends "s".
    #[requires(true)]
    #[ensures(
        // exactly three possible length‐cases
        (s.len() == 0 && result.len() == 0)
        ||
        (s.len() > 0 && s[s.len() - 1] == 's' && result.len() == s.len() + 2)
        ||
        (s.len() > 0 && s[s.len() - 1] != 's' && result.len() == s.len() + 1)
    )]
    #[ensures(
        // always preserves the original prefix
        forall |i: usize| i < s.len() ==> result[i] == s[i]
    )]
    #[ensures(
        // if we added "es", those are the two new chars
        s.len() > 0 && s[s.len()-1] == 's' ==>
          result[s.len()]   == 'e'
       && result[s.len()+1] == 's'
    )]
    #[ensures(
        // if we added just "s", that's the new final char
        s.len() > 0 && s[s.len()-1] != 's' ==>
          result[s.len()] == 's'
    )]
    fn solve(s: &Vec<char>) -> Vec<char> {
        // Create a mutable copy of the input
        let mut result = s.clone();

        // Check the last character and append the appropriate suffix
        if let Some(&last_char) = s.last() {
            if last_char == 's' {
                result.push('e');
                result.push('s');
            } else {
                result.push('s');
            }
        }

        result
    }

    fn main() {
        let word1: Vec<char> = "dog".chars().collect();
        let word2: Vec<char> = "bus".chars().collect();
        let word3: Vec<char> = "glass".chars().collect();

        let plural1 = solve(&word1);
        let plural2 = solve(&word2);
        let plural3 = solve(&word3);

        println!("{}", plural1.iter().collect::<String>()); // "dogs"
        println!("{}", plural2.iter().collect::<String>()); // "buses"
        println!("{}", plural3.iter().collect::<String>()); // "glasses"
    }
}